var REL_ET={lover:'lover',ex:'lover',crush:'first',mutual:'first',almost:'first',tension:'hate',friend:'casual',stranger:'casual',fwb:'casual'};
function MK(k){return HK.EroT3?HK.EroT3.mark(k):'';}
